CREATE TRIGGER scene_versions_immutable BEFORE UPDATE ON scene_versions WHEN NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.scene_id IS NOT OLD.scene_id OR NEW.script_version_id IS NOT OLD.script_version_id OR NEW.parent_version_id IS NOT OLD.parent_version_id OR NEW.version_no IS NOT OLD.version_no OR NEW.narration IS NOT OLD.narration OR NEW.direction_json IS NOT OLD.direction_json OR NEW.duration_ms IS NOT OLD.duration_ms OR NEW.generation_scope IS NOT OLD.generation_scope OR NEW.hash IS NOT OLD.hash OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'VERSION_IMMUTABLE'); END;
